import Image from 'next/image'
import { cn } from '@/lib/utils'

export type ArticleBlock = { heading?: string; paragraphs: string[] }

export type ArticleLayoutProps = {
  body: ArticleBlock[]
  /** Data exibida (já formatada) e valor ISO para o `<time>`. */
  date: { label: string; dateTime: string }
  image?: { src: string; alt: string }
  author?: string
  category?: string
  quote?: string
  /** `cover`: sem imagem no corpo (a capa fica no hero) e metadados centralizados. */
  variant?: 'classic' | 'cover' | 'sidebar' | 'magazine'
  wordsPerMinute?: number
  labels?: {
    authorPrefix?: string
    readingTime?: (minutes: number) => string
    aboutTitle?: string
    publishedLabel?: string
    categoryLabel?: string
    readingLabel?: string
    tocTitle?: string
  }
  aside?: { title: string; description?: string; action: { label: string; href: string } }
  className?: string
}

const sectionId = (index: number) => `secao-${index + 1}`

export function ArticleLayout({
  body,
  date,
  image,
  author,
  category,
  quote,
  variant = 'classic',
  wordsPerMinute = 200,
  labels = {},
  aside,
  className,
}: ArticleLayoutProps) {
  const {
    authorPrefix = 'Por',
    readingTime = (minutes: number) => `${minutes} min de leitura`,
    aboutTitle = 'Sobre o artigo',
    publishedLabel = 'Publicado em',
    categoryLabel = 'Categoria',
    readingLabel = 'Leitura',
    tocTitle = 'Neste artigo',
  } = labels
  const words = body
    .flatMap((block) => block.paragraphs)
    .join(' ')
    .split(/\s+/).length
  const reading = readingTime(Math.max(1, Math.round(words / wordsPerMinute)))

  const meta = (
    <p className="flex flex-wrap gap-x-2 text-sm text-muted-foreground">
      {author ? (
        <span>
          {authorPrefix} {author} ·
        </span>
      ) : null}
      <time dateTime={date.dateTime}>{date.label}</time>
      <span aria-hidden>·</span>
      <span>{reading}</span>
    </p>
  )

  const cover = image ? (
    <div className="relative aspect-video overflow-hidden rounded-2xl bg-muted">
      <Image
        src={image.src}
        alt={image.alt}
        fill
        sizes="(min-width: 1024px) 48rem, 100vw"
        className="object-cover"
      />
    </div>
  ) : null

  const renderBlocks = (from = 0, to = body.length, numbered = false) =>
    body.slice(from, to).map((block, offset) => {
      const index = from + offset
      const number = body.slice(0, index + 1).filter((item) => item.heading).length
      return (
        <section key={block.heading ?? index} id={sectionId(index)} className="mt-10 scroll-mt-28">
          {block.heading ? (
            <h2 className="flex items-baseline gap-3 text-xl font-bold tracking-tight md:text-2xl">
              {numbered ? (
                <span className="font-mono text-base text-primary">
                  {String(number).padStart(2, '0')}
                </span>
              ) : null}
              {block.heading}
            </h2>
          ) : null}
          {block.paragraphs.map((paragraph, index) => (
            <p key={index} className="mt-4 leading-7 text-muted-foreground">
              {paragraph}
            </p>
          ))}
        </section>
      )
    })

  if (variant === 'sidebar') {
    const toc = body
      .map((block, index) => ({ heading: block.heading, id: sectionId(index) }))
      .filter((item): item is { heading: string; id: string } => !!item.heading)

    return (
      <div
        className={cn(
          'container grid gap-12 py-16 md:py-24 lg:grid-cols-[minmax(0,1fr)_18rem]',
          className,
        )}
      >
        <article className="min-w-0">
          {cover}
          {renderBlocks()}
        </article>
        <aside className="space-y-6 self-start lg:sticky lg:top-28">
          <div className="rounded-2xl border bg-card p-6">
            <h2 className="text-sm font-semibold uppercase tracking-[0.2em] text-primary">
              {aboutTitle}
            </h2>
            <dl className="mt-4 space-y-3 text-sm">
              <div>
                <dt className="text-muted-foreground">{publishedLabel}</dt>
                <dd className="font-medium">
                  <time dateTime={date.dateTime}>{date.label}</time>
                </dd>
              </div>
              {category ? (
                <div>
                  <dt className="text-muted-foreground">{categoryLabel}</dt>
                  <dd className="font-medium">{category}</dd>
                </div>
              ) : null}
              <div>
                <dt className="text-muted-foreground">{readingLabel}</dt>
                <dd className="font-medium">{reading}</dd>
              </div>
            </dl>
          </div>
          {toc.length ? (
            <nav aria-label={tocTitle} className="rounded-2xl border bg-card p-6">
              <h2 className="text-sm font-semibold uppercase tracking-[0.2em] text-primary">
                {tocTitle}
              </h2>
              <ol className="mt-4 space-y-2 text-sm">
                {toc.map((item) => (
                  <li key={item.id}>
                    <a
                      href={`#${item.id}`}
                      className="text-muted-foreground transition-colors hover:text-primary"
                    >
                      {item.heading}
                    </a>
                  </li>
                ))}
              </ol>
            </nav>
          ) : null}
          {aside ? (
            <div className="rounded-2xl bg-primary p-6 text-primary-foreground">
              <h2 className="text-lg font-semibold">{aside.title}</h2>
              {aside.description ? (
                <p className="mt-2 text-sm text-primary-foreground/85">{aside.description}</p>
              ) : null}
              <a
                href={aside.action.href}
                className="mt-4 inline-flex rounded-full bg-primary-foreground px-4 py-2 text-sm font-semibold text-primary transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-foreground focus-visible:ring-offset-2 focus-visible:ring-offset-primary"
              >
                {aside.action.label}
              </a>
            </div>
          ) : null}
        </aside>
      </div>
    )
  }

  if (variant === 'magazine') {
    const [lead, ...rest] = body
    const quoteAfter = Math.min(1, rest.length - 1)

    return (
      <article className={cn('container max-w-3xl py-16 md:py-24', className)}>
        <div className="border-b pb-8">{meta}</div>
        {lead?.paragraphs.map((paragraph, index) => (
          <p
            key={index}
            className={cn(
              'mt-8 text-lg leading-8 text-foreground md:text-xl md:leading-9',
              index === 0 &&
                'first-letter:float-left first-letter:mr-3 first-letter:text-6xl first-letter:font-bold first-letter:leading-none first-letter:text-primary',
            )}
          >
            {paragraph}
          </p>
        ))}
        {rest.map((block, index) => (
          <div key={block.heading ?? index}>
            {renderBlocks(index + 1, index + 2, true)}
            {quote && index === quoteAfter ? (
              <blockquote className="mt-10 border-l-4 border-primary pl-6 text-xl font-medium leading-8 md:text-2xl md:leading-10">
                {quote}
              </blockquote>
            ) : null}
          </div>
        ))}
      </article>
    )
  }

  if (variant === 'cover') {
    return (
      <article className={cn('container max-w-3xl py-16 md:py-24', className)}>
        <div className="flex justify-center border-b pb-8">{meta}</div>
        {renderBlocks()}
      </article>
    )
  }

  return (
    <article className={cn('container max-w-3xl py-16 md:py-24', className)}>
      {meta}
      {cover ? <div className="mt-6">{cover}</div> : null}
      {renderBlocks()}
    </article>
  )
}

import {
  ArticleLayout,
  type ArticleBlock,
  type ArticleLayoutProps,
} from '@/components/library/content/ArticleLayout'
import { BlogGrid, type BlogGridProps } from '@/components/library/data-display/BlogGrid'
import { HeroImage } from '@/components/library/marketing/HeroImage'
import { HeroSplit } from '@/components/library/marketing/HeroSplit'
import { PageHeader } from '@/components/library/marketing/PageHeader'

export type BlogPostContent = {
  title: string
  excerpt?: string
  category?: string
  author?: string
  image: { src: string; alt: string }
  date: { label: string; dateTime: string }
  body: ArticleBlock[]
  quote?: string
}

export type BlogPostPageProps = {
  post: BlogPostContent
  /**
   * - `classic`: cabeçalho, imagem e texto em coluna única.
   * - `cover`: capa em tela cheia com o título sobre a imagem.
   * - `sidebar`: texto com barra lateral fixa (dados, índice e chamada).
   * - `magazine`: banner dividido, abertura em destaque, seções numeradas e citação.
   */
  layout?: 'classic' | 'cover' | 'sidebar' | 'magazine'
  breadcrumbs?: Array<{ label: string; href?: string }>
  related?: BlogGridProps['posts']
  relatedTitle?: string
  labels?: ArticleLayoutProps['labels']
  aside?: ArticleLayoutProps['aside']
  className?: string
}

export function BlogPostPage({
  post,
  layout = 'classic',
  breadcrumbs,
  related = [],
  relatedTitle = 'Leia também',
  labels,
  aside,
  className,
}: BlogPostPageProps) {
  const header =
    layout === 'cover' ? (
      <HeroImage
        eyebrow={post.category}
        title={post.title}
        description={post.excerpt}
        image={post.image}
        align="center"
      />
    ) : layout === 'magazine' ? (
      <HeroSplit
        eyebrow={post.category}
        title={post.title}
        description={post.excerpt}
        image={post.image}
        imagePosition="left"
      />
    ) : (
      <PageHeader
        eyebrow={post.category}
        title={post.title}
        description={post.excerpt}
        breadcrumbs={breadcrumbs}
        size="compact"
        variant={breadcrumbs?.length ? 'primary' : 'muted'}
      />
    )

  return (
    <div className={className}>
      {header}
      <ArticleLayout
        variant={layout}
        body={post.body}
        date={post.date}
        image={post.image}
        author={post.author}
        category={post.category}
        quote={post.quote}
        labels={labels}
        aside={aside}
      />
      {related.length ? (
        <BlogGrid title={relatedTitle} posts={related.slice(0, 3)} className="bg-muted/40" />
      ) : null}
    </div>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { ArrowRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type BlogGridProps = {
  title?: string
  posts: Array<{
    slug: string
    title: string
    excerpt?: string
    image: { src: string; alt: string }
    date: string
    category?: string
    href?: string
  }>
  className?: string
}

export function BlogGrid({ title, posts, className }: BlogGridProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'blog-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="blog-title" className="mb-10 text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        <div className="grid gap-7 md:grid-cols-2 lg:grid-cols-3">
          {posts.map((post) => (
            <article
              key={post.slug}
              className="group overflow-hidden rounded-2xl border bg-card shadow-sm"
            >
              <Link
                href={post.href ?? `/blog/${post.slug}`}
                className="block focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <div className="relative aspect-video overflow-hidden bg-muted">
                  <Image
                    src={post.image.src}
                    alt={post.image.alt}
                    fill
                    className="object-cover transition duration-500 group-hover:scale-105"
                    sizes="(min-width: 1024px) 33vw, 50vw"
                  />
                </div>
                <div className="p-6">
                  <div className="flex gap-2 text-xs font-medium text-muted-foreground">
                    {post.category ? <span>{post.category}</span> : null}
                    <time dateTime={post.date}>{post.date}</time>
                  </div>
                  <h3 className="mt-3 text-xl font-semibold">{post.title}</h3>
                  {post.excerpt ? (
                    <p className="mt-2 line-clamp-3 text-sm leading-6 text-muted-foreground">
                      {post.excerpt}
                    </p>
                  ) : null}
                  <span className="mt-5 inline-flex items-center gap-2 text-sm font-semibold text-primary">
                    Ler artigo <ArrowRight className="h-4 w-4" aria-hidden="true" />
                  </span>
                </div>
              </Link>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

