export type HeroImageProps = {
  title: string
  description?: string
  image: { src: string; alt: string }
  eyebrow?: string
  primaryAction?: { label: string; href: string }
  secondaryAction?: { label: string; href: string }
  align?: 'left' | 'center'
  className?: string
}

export function HeroImage({
  title,
  description,
  image,
  eyebrow,
  primaryAction,
  secondaryAction,
  align = 'left',
  className,
}: HeroImageProps) {
  return (
    <section
      className={cn(
        'relative isolate min-h-[560px] overflow-hidden bg-slate-950 text-white',
        className,
      )}
      aria-labelledby="hero-image-title"
    >
      <Image
        src={image.src}
        alt={image.alt}
        fill
        priority
        className="object-cover opacity-55"
        sizes="100vw"
      />
      <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/45 to-transparent" />
      <div
        className={cn(
          'container relative z-10 flex min-h-[560px] flex-col justify-center py-20',
          align === 'center' && 'items-center text-center',
        )}
      >
        {eyebrow ? (
          <p className="mb-4 text-sm font-semibold uppercase tracking-[0.2em]">{eyebrow}</p>
        ) : null}
        <h1
          id="hero-image-title"
          className="max-w-4xl text-4xl font-bold tracking-tight sm:text-6xl"
        >
          {title}
        </h1>
        {description ? <p className="mt-6 max-w-2xl text-lg text-white/80">{description}</p> : null}
        {(primaryAction || secondaryAction) && (
          <div className="mt-8 flex flex-wrap gap-3">
            {primaryAction ? (
              <Button asChild size="lg">
                <Link href={primaryAction.href}>{primaryAction.label}</Link>
              </Button>
            ) : null}
            {secondaryAction ? (
              <Button asChild size="lg" variant="secondary">
                <Link href={secondaryAction.href}>{secondaryAction.label}</Link>
              </Button>
            ) : null}
          </div>
        )}
      </div>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type HeroSplitProps = {
  title: string
  description?: string
  image: { src: string; alt: string }
  eyebrow?: string
  action?: { label: string; href: string }
  imagePosition?: 'left' | 'right'
  className?: string
}

export function HeroSplit({
  title,
  description,
  image,
  eyebrow,
  action,
  imagePosition = 'right',
  className,
}: HeroSplitProps) {
  return (
    <section
      className={cn('overflow-hidden border-b bg-background', className)}
      aria-labelledby="hero-split-title"
    >
      <div className="container grid min-h-[520px] items-center gap-10 py-12 lg:grid-cols-2 lg:py-20">
        <div className={cn('max-w-xl', imagePosition === 'left' && 'lg:order-2')}>
          {eyebrow ? (
            <p className="mb-3 text-sm font-semibold uppercase tracking-widest text-primary">
              {eyebrow}
            </p>
          ) : null}
          <h1 id="hero-split-title" className="text-4xl font-bold tracking-tight sm:text-5xl">
            {title}
          </h1>
          {description ? (
            <p className="mt-5 text-lg leading-8 text-muted-foreground">{description}</p>
          ) : null}
          {action ? (
            <Button asChild className="mt-8" size="lg">
              <Link href={action.href}>{action.label}</Link>
            </Button>
          ) : null}
        </div>
        <div
          className={cn(
            'relative aspect-[4/3] overflow-hidden rounded-3xl bg-muted shadow-xl',
            imagePosition === 'left' && 'lg:order-1',
          )}
        >
          <Image
            src={image.src}
            alt={image.alt}
            fill
            priority
            className="object-cover"
            sizes="(min-width: 1024px) 50vw, 100vw"
          />
        </div>
      </div>
    </section>
  )
}

import Link from 'next/link'
import { ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type PageHeaderProps = {
  title: string
  description?: string
  eyebrow?: string
  breadcrumbs?: Array<{ label: string; href?: string }>
  align?: 'left' | 'center'
  size?: 'default' | 'compact'
  variant?: 'muted' | 'primary'
  className?: string
}

export function PageHeader({
  title,
  description,
  eyebrow,
  breadcrumbs,
  align = 'left',
  size = 'default',
  variant = 'muted',
  className,
}: PageHeaderProps) {
  const compact = size === 'compact'
  const primary = variant === 'primary'

  return (
    <header
      className={cn(
        primary
          ? 'bg-primary bg-gradient-to-br from-primary to-primary/80 text-primary-foreground'
          : 'border-b bg-muted/30',
        className,
      )}
    >
      <div
        className={cn(
          'container',
          compact ? 'py-8 md:py-10' : 'py-14 md:py-20',
          align === 'center' && 'text-center',
        )}
      >
        {breadcrumbs?.length ? (
          <nav
            aria-label="Navegação estrutural"
            className={cn(compact ? 'mb-3' : 'mb-6', align === 'center' && 'flex justify-center')}
          >
            <ol
              className={cn(
                'flex flex-wrap items-center gap-1',
                compact ? 'text-xs' : 'text-sm',
                primary ? 'text-primary-foreground/70' : 'text-muted-foreground',
              )}
            >
              {breadcrumbs.map((item, index) => (
                <li key={`${item.label}-${index}`} className="flex items-center gap-1">
                  {index > 0 ? (
                    <ChevronRight className={compact ? 'h-3 w-3' : 'h-4 w-4'} aria-hidden="true" />
                  ) : null}
                  {item.href ? (
                    <Link
                      href={item.href}
                      className={cn(
                        'hover:underline',
                        primary ? 'hover:text-primary-foreground' : 'hover:text-foreground',
                      )}
                    >
                      {item.label}
                    </Link>
                  ) : (
                    <span
                      aria-current="page"
                      className={cn(primary && 'font-medium text-primary-foreground')}
                    >
                      {item.label}
                    </span>
                  )}
                </li>
              ))}
            </ol>
          </nav>
        ) : null}
        {eyebrow ? (
          <p
            className={cn(
              'font-semibold uppercase tracking-widest',
              compact ? 'mb-2 text-xs' : 'mb-3 text-sm',
              primary ? 'text-primary-foreground/80' : 'text-primary',
            )}
          >
            {eyebrow}
          </p>
        ) : null}
        <h1
          className={cn(
            'font-bold tracking-tight',
            compact ? 'text-2xl sm:text-3xl' : 'text-4xl sm:text-5xl',
          )}
        >
          {title}
        </h1>
        {description ? (
          <p
            className={cn(
              'max-w-2xl',
              compact ? 'mt-2 text-base' : 'mt-4 text-lg',
              primary ? 'text-primary-foreground/80' : 'text-muted-foreground',
              align === 'center' && 'mx-auto',
            )}
          >
            {description}
          </p>
        ) : null}
      </div>
    </header>
  )
}

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'

const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground shadow hover:bg-primary/90',
        destructive: 'bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90',
        outline:
          'border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline',
      },
      size: {
        default: 'h-9 px-4 py-2',
        sm: 'h-8 rounded-md px-3 text-xs',
        lg: 'h-10 rounded-md px-8',
        icon: 'h-9 w-9',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />
    )
  },
)
Button.displayName = 'Button'

export { Button, buttonVariants }

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
